class Solution:
    def pyramidTransition(self, bottom: str, allowed: List[str]) -> bool:
        from collections import defaultdict
        pairs = defaultdict(list)
        for a, b, c in allowed:
            pairs[a + b].append(c)
        failed = set()

        def dfs(row):
            if len(row) == 1:
                return True
            if row in failed:
                return False
            opts = [pairs[row[i:i+2]] for i in range(len(row) - 1)]
            if any(not o for o in opts):
                failed.add(row)
                return False
            def build(i, nxt):
                if i == len(opts):
                    return dfs(nxt)
                for ch in opts[i]:
                    if build(i + 1, nxt + ch):
                        return True
                return False
            if not build(0, ""):
                failed.add(row)
                return False
            return True

        return dfs(bottom)

