class Solution {
public:
    unordered_map<string, vector<char>> pairs;
    unordered_set<string> failed;

    bool dfs(const string& row) {
        if (row.size() == 1) return true;
        if (failed.count(row)) return false;
        vector<vector<char>> opts;
        for (int i = 0; i + 1 < (int)row.size(); i++) {
            auto it = pairs.find(row.substr(i, 2));
            if (it == pairs.end()) { failed.insert(row); return false; }
            opts.push_back(it->second);
        }
        string nxt;
        function<bool(int)> build = [&](int i) -> bool {
            if (i == (int)opts.size()) return dfs(nxt);
            for (char c : opts[i]) {
                nxt.push_back(c);
                if (build(i + 1)) return true;
                nxt.pop_back();
            }
            return false;
        };
        if (!build(0)) { failed.insert(row); return false; }
        return true;
    }

    bool pyramidTransition(string bottom, vector<string>& allowed) {
        for (auto& s : allowed) pairs[s.substr(0, 2)].push_back(s[2]);
        return dfs(bottom);
    }
};

