class Solution {
    private Map<String, List<Character>> pairs = new HashMap<>();
    private Set<String> failed = new HashSet<>();

    public boolean pyramidTransition(String bottom, List<String> allowed) {
        for (String s : allowed)
            pairs.computeIfAbsent(s.substring(0, 2), k -> new ArrayList<>()).add(s.charAt(2));
        return dfs(bottom);
    }

    private boolean dfs(String row) {
        if (row.length() == 1) return true;
        if (failed.contains(row)) return false;
        List<List<Character>> opts = new ArrayList<>();
        for (int i = 0; i + 1 < row.length(); i++) {
            List<Character> o = pairs.get(row.substring(i, i + 2));
            if (o == null) { failed.add(row); return false; }
            opts.add(o);
        }
        StringBuilder sb = new StringBuilder();
        if (!build(0, opts, sb)) { failed.add(row); return false; }
        return true;
    }

    private boolean build(int i, List<List<Character>> opts, StringBuilder sb) {
        if (i == opts.size()) return dfs(sb.toString());
        for (char c : opts.get(i)) {
            sb.append(c);
            if (build(i + 1, opts, sb)) return true;
            sb.deleteCharAt(sb.length() - 1);
        }
        return false;
    }
}

