var pyramidTransition = function(bottom, allowed) {
    const pairs = new Map();
    for (const [a, b, c] of allowed) {
        const k = a + b;
        if (!pairs.has(k)) pairs.set(k, []);
        pairs.get(k).push(c);
    }
    const failed = new Set();

    function dfs(row) {
        if (row.length === 1) return true;
        if (failed.has(row)) return false;
        const opts = [];
        for (let i = 0; i + 1 < row.length; i++) {
            const o = pairs.get(row.slice(i, i + 2));
            if (!o) { failed.add(row); return false; }
            opts.push(o);
        }
        function build(i, nxt) {
            if (i === opts.length) return dfs(nxt);
            for (const c of opts[i])
                if (build(i + 1, nxt + c)) return true;
            return false;
        }
        if (!build(0, "")) { failed.add(row); return false; }
        return true;
    }
    return dfs(bottom);
};

