class Solution:
    def pyramidTransition(self, bottom: str, allowed: List[str]) -> bool:
        trans = [[0] * 7 for _ in range(7)]
        for a, b, c in allowed:
            trans[ord(a) - 65][ord(b) - 65] |= 1 << (ord(c) - 65)
        cur = [1 << (ord(ch) - 65) for ch in bottom]
        while len(cur) > 1:
            nxt = []
            for i in range(len(cur) - 1):
                m = 0
                x, y = cur[i], cur[i + 1]
                for a in range(7):
                    if x >> a & 1:
                        for b in range(7):
                            if y >> b & 1:
                                m |= trans[a][b]
                if m == 0:
                    return False
                nxt.append(m)
            cur = nxt
        return cur[0] != 0

