class Solution {
public:
    bool pyramidTransition(string bottom, vector<string>& allowed) {
        int trans[7][7] = {};
        for (auto& s : allowed)
            trans[s[0]-'A'][s[1]-'A'] |= 1 << (s[2]-'A');
        vector<int> cur;
        for (char ch : bottom) cur.push_back(1 << (ch - 'A'));
        while (cur.size() > 1) {
            vector<int> nxt;
            for (int i = 0; i + 1 < (int)cur.size(); i++) {
                int m = 0;
                for (int a = 0; a < 7; a++)
                    if (cur[i] >> a & 1)
                        for (int b = 0; b < 7; b++)
                            if (cur[i+1] >> b & 1) m |= trans[a][b];
                if (!m) return false;
                nxt.push_back(m);
            }
            cur = move(nxt);
        }
        return cur[0] != 0;
    }
};

