class Solution {
    public boolean pyramidTransition(String bottom, List<String> allowed) {
        int[][] trans = new int[7][7];
        for (String s : allowed)
            trans[s.charAt(0)-'A'][s.charAt(1)-'A'] |= 1 << (s.charAt(2)-'A');
        List<Integer> cur = new ArrayList<>();
        for (char ch : bottom.toCharArray()) cur.add(1 << (ch - 'A'));
        while (cur.size() > 1) {
            List<Integer> nxt = new ArrayList<>();
            for (int i = 0; i + 1 < cur.size(); i++) {
                int m = 0;
                for (int a = 0; a < 7; a++)
                    if ((cur.get(i) >> a & 1) != 0)
                        for (int b = 0; b < 7; b++)
                            if ((cur.get(i+1) >> b & 1) != 0) m |= trans[a][b];
                if (m == 0) return false;
                nxt.add(m);
            }
            cur = nxt;
        }
        return cur.get(0) != 0;
    }
}

